
-- GP01 | Gestão de Privacidade | Iniciante
INSERT INTO public.tb_competencias(fk_dominio_conhecimento, fk_area_conhecimento, fk_dificuldade, no_origem_competencias_pt, no_origem_competencias_en, no_competencias_pt, no_competencias_en, ds_competencias_pt, ds_competencias_en)
VALUES (1, 1, 1, 'Lei nº 13.709/2018 (LGPD); ISO/IEC 29100', 'Law nº 13.709/2018 (LGPD); ISO/IEC 29100', 'Fundamentos legais da proteção de dados pessoais', 'Legal foundations for the protection of personal data', 'Conhecimento sobre dados pessoais e dados pessoais sensíveis, operações de tratamento, princípios da LGPD e direitos e deveres básicos aplicáveis à proteção de dados pessoais. A formulação substitui o uso da tríade confidencialidade, integridade e disponibilidade como definição de privacidade.', 'Knowledge regarding personal data and sensitive personal data, processing operations, the principles of the LGPD (General Personal Data Protection Law), and the basic rights and obligations applicable to personal data protection. This formulation replaces the use of the triad of confidentiality, integrity, and availability as a definition of privacy.');

-- GP02 | Gestão de Privacidade | Iniciante
INSERT INTO public.tb_competencias(fk_dominio_conhecimento, fk_area_conhecimento, fk_dificuldade, no_origem_competencias_pt, no_origem_competencias_en, no_competencias_pt, no_competencias_en, ds_competencias_pt, ds_competencias_en)
VALUES (1, 1, 1, 'Lei nº 13.709/2018 (LGPD)', 'Law nº 13.709/2018 (LGPD)', 'Direitos dos titulares de dados pessoais', 'Rights of personal data subjects', 'Conhecimento sobre os direitos de confirmação, acesso, correção, anonimização, bloqueio, eliminação, informação, revogação, oposição, revisão e portabilidade, quando aplicáveis.', 'Knowledge of the rights to confirmation, access, correction, anonymization, blocking, erasure, information, withdrawal of consent, objection, review, and portability, where applicable.');

-- GP03 | Gestão de Privacidade | Iniciante
INSERT INTO public.tb_competencias(fk_dominio_conhecimento, fk_area_conhecimento, fk_dificuldade, no_origem_competencias_pt, no_origem_competencias_en, no_competencias_pt, no_competencias_en, ds_competencias_pt, ds_competencias_en)
VALUES (1, 1, 1, 'Lei nº 13.709/2018 (LGPD); ISO/IEC 29184; ANPD - Guia Orientativo: Cookies e Proteção de Dados Pessoais', 'Law nº 13.709/2018 (LGPD); ISO/IEC 29184; ANPD - Guidance on Cookies and Personal Data Protection', 'Consentimento e revogação', 'Consent and withdrawal of consent', 'Conhecimento sobre requisitos de validade, demonstração, gestão e revogação do consentimento, bem como sobre situações em que outra hipótese legal deve ser utilizada.', 'Knowledge of the requirements for the validity, demonstration, management, and withdrawal of consent, as well as situations in which another legal basis must be used.');

-- GP04 | Gestão de Privacidade | Iniciante
INSERT INTO public.tb_competencias(fk_dominio_conhecimento, fk_area_conhecimento, fk_dificuldade, no_origem_competencias_pt, no_origem_competencias_en, no_competencias_pt, no_competencias_en, ds_competencias_pt, ds_competencias_en)
VALUES (1, 1, 1, 'Lei nº 13.709/2018 (LGPD); ANPD - Guia Orientativo para Definições dos Agentes de Tratamento de Dados Pessoais e do Encarregado; Resolução CD/ANPD nº 18/2024', 'Law nº 13.709/2018 (LGPD); ANPD - Guidance on the Definitions of Personal Data Processing Agents and the Data Protection Officer; CD/ANPD Resolution nº 18/2024', 'Identificação dos agentes de tratamento e designação do encarregado', 'Identification of processing agents and appointment of the data protection officer', 'Conhecimento para distinguir controlador, controladoria conjunta, operador e suboperador a partir das decisões e operações de tratamento, bem como compreender os requisitos para designação formal do encarregado.', 'Knowledge to distinguish controllers, joint controllers, processors, and sub-processors based on processing decisions and operations, and to understand the requirements for formally appointing the data protection officer.');

-- GP05 | Gestão de Privacidade | Iniciante
INSERT INTO public.tb_competencias(fk_dominio_conhecimento, fk_area_conhecimento, fk_dificuldade, no_origem_competencias_pt, no_origem_competencias_en, no_competencias_pt, no_competencias_en, ds_competencias_pt, ds_competencias_en)
VALUES (1, 1, 1, 'Lei nº 13.709/2018 (LGPD); Resolução CD/ANPD nº 18/2024; ANPD - Guia Orientativo: Atuação do Encarregado pelo Tratamento de Dados Pessoais', 'Law nº 13.709/2018 (LGPD); CD/ANPD Resolution nº 18/2024; ANPD - Guidance on the Role of the Data Protection Officer', 'Atuação e atribuições do encarregado', 'Role and responsibilities of the data protection officer', 'Conhecimento sobre atribuições, autonomia, canais de comunicação, deveres, apoio organizacional e relacionamento do encarregado com titulares, agentes de tratamento e ANPD, incluindo independência técnica e imparcialidade no aconselhamento, prevenção de conflitos de interesse e articulação institucional.', 'Knowledge of the data protection officer''s responsibilities, autonomy, communication channels, duties, organizational support, and relationships with data subjects, processing agents, and the ANPD, including technical independence and impartiality in advising, prevention of conflicts of interest, and institutional coordination.');

-- GP06 | Gestão de Privacidade | Iniciante
INSERT INTO public.tb_competencias(fk_dominio_conhecimento, fk_area_conhecimento, fk_dificuldade, no_origem_competencias_pt, no_origem_competencias_en, no_competencias_pt, no_competencias_en, ds_competencias_pt, ds_competencias_en)
VALUES (1, 1, 1, 'Lei nº 13.709/2018 (LGPD); ANPD - Guia Orientativo para Definições dos Agentes de Tratamento de Dados Pessoais e do Encarregado', 'Law nº 13.709/2018 (LGPD); ANPD - Guidance on the Definitions of Personal Data Processing Agents and the Data Protection Officer', 'Responsabilidades dos agentes de tratamento', 'Responsibilities of processing agents', 'Conhecimento sobre obrigações do controlador e do operador, instruções de tratamento, responsabilidade por danos e hipóteses de responsabilização solidária previstas na LGPD.', 'Knowledge of controller and processor obligations, processing instructions, liability for damages, and the situations of joint and several liability provided for in the LGPD.');

-- GP07 | Gestão de Privacidade | Iniciante
INSERT INTO public.tb_competencias(fk_dominio_conhecimento, fk_area_conhecimento, fk_dificuldade, no_origem_competencias_pt, no_origem_competencias_en, no_competencias_pt, no_competencias_en, ds_competencias_pt, ds_competencias_en)
VALUES (1, 1, 1, 'Portaria SGD/MGI nº 852/2023', 'SGD/MGI Ordinance nº 852/2023', 'Programa de Privacidade e Segurança da Informação no âmbito da APF', 'Privacy and Information Security Program within the Federal Public Administration', 'Conhecimento sobre instituição, objetivos, governança e responsabilidades do Programa de Privacidade e Segurança da Informação, com foco nos componentes de privacidade.', 'Knowledge of the establishment, objectives, governance, and responsibilities of the Privacy and Information Security Program, focusing on its privacy components.');

-- GP08 | Gestão de Privacidade | Básico
INSERT INTO public.tb_competencias(fk_dominio_conhecimento, fk_area_conhecimento, fk_dificuldade, no_origem_competencias_pt, no_origem_competencias_en, no_competencias_pt, no_competencias_en, ds_competencias_pt, ds_competencias_en)
VALUES (1, 1, 2, 'Lei nº 13.709/2018 (LGPD); Assessment of Competences for LGPD DPO through ANPD Standard and Information Systems Curriculum', 'Law nº 13.709/2018 (LGPD); Assessment of Competences for LGPD DPO through ANPD Standard and Information Systems Curriculum', 'Atendimento e gestão de solicitações dos titulares', 'Handling and management of data subject requests', 'Conhecimento sobre o recebimento, a autenticação, a análise, o encaminhamento, a resposta, o registro e o acompanhamento de solicitações relativas ao exercício dos direitos dos titulares.', 'Knowledge of receiving, authenticating, analyzing, forwarding, responding to, recording, and tracking requests concerning the exercise of data subject rights.');

-- GP09 | Gestão de Privacidade | Básico
INSERT INTO public.tb_competencias(fk_dominio_conhecimento, fk_area_conhecimento, fk_dificuldade, no_origem_competencias_pt, no_origem_competencias_en, no_competencias_pt, no_competencias_en, ds_competencias_pt, ds_competencias_en)
VALUES (1, 1, 2, 'Lei nº 13.709/2018 (LGPD)', 'Law nº 13.709/2018 (LGPD)', 'Tratamento de dados pessoais sensíveis', 'Processing of sensitive personal data', 'Conhecimento sobre hipóteses legais, limitações, salvaguardas e riscos específicos do tratamento de dados pessoais sensíveis.', 'Knowledge of the legal bases, limitations, safeguards, and specific risks associated with processing sensitive personal data.');

-- GP10 | Gestão de Privacidade | Básico
INSERT INTO public.tb_competencias(fk_dominio_conhecimento, fk_area_conhecimento, fk_dificuldade, no_origem_competencias_pt, no_origem_competencias_en, no_competencias_pt, no_competencias_en, ds_competencias_pt, ds_competencias_en)
VALUES (1, 1, 2, 'Lei nº 13.709/2018 (LGPD); Assessment of Competences for LGPD DPO through ANPD Standard and Information Systems Curriculum; Data Protection Compliance Part 1: Know Your Data - Mapping the 5 W''s', 'Law nº 13.709/2018 (LGPD); Assessment of Competences for LGPD DPO through ANPD Standard and Information Systems Curriculum; Data Protection Compliance Part 1: Know Your Data - Mapping the 5 W''s', 'Registro das operações de tratamento de dados pessoais', 'Records of personal data processing activities', 'Conhecimento sobre identificação, registro, atualização e rastreabilidade das operações de tratamento e de suas principais características, incluindo finalidades, dados, titulares, agentes, compartilhamentos, retenção e bases legais.', 'Knowledge of identifying, recording, updating, and tracing processing operations and their main characteristics, including purposes, data, data subjects, processing agents, sharing arrangements, retention, and legal bases.');

-- GP11 | Gestão de Privacidade | Básico
INSERT INTO public.tb_competencias(fk_dominio_conhecimento, fk_area_conhecimento, fk_dificuldade, no_origem_competencias_pt, no_origem_competencias_en, no_competencias_pt, no_competencias_en, ds_competencias_pt, ds_competencias_en)
VALUES (1, 1, 2, 'Lei nº 13.709/2018 (LGPD); Lei nº 8.159/1991; Lei nº 12.527/2011 (LAI)', 'Law nº 13.709/2018 (LGPD); Law nº 8.159/1991; Law nº 12.527/2011 (LAI)', 'Requisitos legais de retenção, conservação e eliminação de dados', 'Legal requirements for data retention, preservation, and erasure', 'Conhecimento sobre prazos, hipóteses de conservação, deveres de eliminação e restrições arquivísticas aplicáveis a dados pessoais, especialmente no setor público.', 'Knowledge of retention periods, grounds for preservation, erasure duties, and archival restrictions applicable to personal data, particularly in the public sector.');

-- GP12 | Gestão de Privacidade | Básico
INSERT INTO public.tb_competencias(fk_dominio_conhecimento, fk_area_conhecimento, fk_dificuldade, no_origem_competencias_pt, no_origem_competencias_en, no_competencias_pt, no_competencias_en, ds_competencias_pt, ds_competencias_en)
VALUES (1, 1, 2, 'Lei nº 13.709/2018 (LGPD); Resolução CD/ANPD nº 18/2024; Assessment of Competences for LGPD DPO through ANPD Standard and Information Systems Curriculum', 'Law nº 13.709/2018 (LGPD); CD/ANPD Resolution nº 18/2024; Assessment of Competences for LGPD DPO through ANPD Standard and Information Systems Curriculum', 'Relacionamento com a ANPD e outras autoridades de proteção de dados', 'Relations with the ANPD and other data protection authorities', 'Conhecimento sobre canais, solicitações, fiscalizações, investigações, reclamações, prestação de informações e cooperação com a ANPD e, quando aplicável, com reguladores estrangeiros.', 'Knowledge of communication channels, requests, inspections, investigations, complaints, provision of information, and cooperation with the ANPD and, where applicable, foreign regulators.');

-- GP13 | Gestão de Privacidade | Intermediário
INSERT INTO public.tb_competencias(fk_dominio_conhecimento, fk_area_conhecimento, fk_dificuldade, no_origem_competencias_pt, no_origem_competencias_en, no_competencias_pt, no_competencias_en, ds_competencias_pt, ds_competencias_en)
VALUES (1, 1, 3, 'Lei nº 13.709/2018 (LGPD); ANPD - Legítimo Interesse: Hipóteses Legais de Tratamento de Dados Pessoais', 'Law nº 13.709/2018 (LGPD); ANPD - Legitimate Interests: Legal Bases for Personal Data Processing', 'Hipóteses legais de tratamento e legítimo interesse', 'Legal bases for processing and legitimate interests', 'Conhecimento para identificar as hipóteses legais aplicáveis ao tratamento de dados pessoais e compreender os critérios, parâmetros, teste de balanceamento e salvaguardas associados ao legítimo interesse.', 'Knowledge to identify the legal bases applicable to personal data processing and understand the criteria, parameters, balancing test, and safeguards associated with legitimate interests.');

-- GP14 | Gestão de Privacidade | Intermediário
INSERT INTO public.tb_competencias(fk_dominio_conhecimento, fk_area_conhecimento, fk_dificuldade, no_origem_competencias_pt, no_origem_competencias_en, no_competencias_pt, no_competencias_en, ds_competencias_pt, ds_competencias_en)
VALUES (1, 1, 3, 'Lei nº 13.709/2018 (LGPD); regulamentação e orientações vigentes da ANPD sobre comunicação de incidentes', 'Law nº 13.709/2018 (LGPD); current ANPD regulations and guidance on incident notification', 'Obrigações de comunicação de incidentes envolvendo dados pessoais', 'Obligations to notify incidents involving personal data', 'Conhecimento sobre critérios, conteúdo, responsáveis, registros, prazos e procedimentos para comunicação à ANPD e aos titulares quando um incidente puder acarretar risco ou dano relevante, incluindo a articulação com equipes de resposta, a avaliação de impactos aos titulares e a preparação de informações para comunicação.', 'Knowledge of the criteria, content, responsible parties, records, deadlines, and procedures for notifying the ANPD and data subjects when an incident may entail significant risk or harm, including coordination with response teams, assessment of impacts on data subjects, and preparation of information for notification.');

