INSERT INTO public.tb_competencias(fk_dominio_conhecimento, fk_area_conhecimento, fk_dificuldade, no_origem_competencias_pt, no_origem_competencias_en, no_competencias_pt, no_competencias_en, ds_competencias_pt, ds_competencias_en)
VALUES (1, 1, 3, 'Lei nº 12.965/2014 (Marco Civil da Internet)', 'Law nº 12.965/2014 (Brazilian Internet Civil Rights Framework)', 'Privacidade e proteção de dados no Marco Civil da Internet', 'Privacy and data protection under the Brazilian Internet Civil Rights Framework', 'Conhecimento sobre direitos e deveres relacionados à privacidade, proteção de registros e dados pessoais, guarda de registros e fornecimento de informações no uso da internet no Brasil.', 'Knowledge of rights and duties relating to privacy, protection of records and personal data, record retention, and disclosure of information in the use of the internet in Brazil.');

