-- GP20 | Gestão de Privacidade | Avançado
INSERT INTO public.tb_competencias(fk_dominio_conhecimento, fk_area_conhecimento, fk_dificuldade, no_origem_competencias_pt, no_origem_competencias_en, no_competencias_pt, no_competencias_en, ds_competencias_pt, ds_competencias_en)
VALUES (1, 1, 4, 'Lei nº 13.709/2018 (LGPD); Resolução CD/ANPD nº 19/2024; Assessment of Competences for LGPD DPO through ANPD Standard and Information Systems Curriculum', 'Law nº 13.709/2018 (LGPD); CD/ANPD Resolution nº 19/2024; Assessment of Competences for LGPD DPO through ANPD Standard and Information Systems Curriculum', 'Cláusulas contratuais de proteção de dados', 'Data protection contractual clauses', 'Conhecimento para elaborar, analisar e acompanhar cláusulas relativas ao tratamento por operadores, suboperadores e terceiros, incluindo instruções, responsabilidades, auditoria, término e transferências internacionais.', 'Knowledge to draft, analyze, and monitor clauses concerning processing by processors, sub-processors, and third parties, including instructions, responsibilities, auditing, termination, and international transfers.');

-- GP21 | Gestão de Privacidade | Avançado
INSERT INTO public.tb_competencias(fk_dominio_conhecimento, fk_area_conhecimento, fk_dificuldade, no_origem_competencias_pt, no_origem_competencias_en, no_competencias_pt, no_competencias_en, ds_competencias_pt, ds_competencias_en)
VALUES (1, 1, 4, 'Lei nº 13.709/2018 (LGPD); ANPD - Guia Orientativo: Tratamento de Dados Pessoais pelo Poder Público', 'Law nº 13.709/2018 (LGPD); ANPD - Guidance on Personal Data Processing by Public Authorities', 'Tratamento de dados pessoais pelo poder público', 'Processing of personal data by public authorities', 'Conhecimento sobre finalidade pública, competências legais, bases legais, transparência, compartilhamento, divulgação e limites aplicáveis ao tratamento de dados pessoais por órgãos e entidades públicas.', 'Knowledge of public purposes, statutory powers, legal bases, transparency, sharing, disclosure, and limits applicable to personal data processing by public agencies and entities.');

-- GP22 | Gestão de Privacidade | Avançado
INSERT INTO public.tb_competencias(fk_dominio_conhecimento, fk_area_conhecimento, fk_dificuldade, no_origem_competencias_pt, no_origem_competencias_en, no_competencias_pt, no_competencias_en, ds_competencias_pt, ds_competencias_en)
VALUES (1, 1, 4, 'Lei nº 13.709/2018 (LGPD); Lei nº 12.527/2011 (LAI); Decreto nº 7.724/2012; Decreto nº 7.845/2012', 'Law nº 13.709/2018 (LGPD); Law nº 12.527/2011 (LAI); Decree nº 7.724/2012; Decree nº 7.845/2012', 'Aplicação conjunta da LGPD e da LAI', 'Joint application of the LGPD and the Access to Information Law', 'Conhecimento para compatibilizar transparência e acesso à informação com proteção de dados pessoais, sigilo, classificação da informação e restrições de acesso no setor público.', 'Knowledge to reconcile transparency and access to information with personal data protection, confidentiality, information classification, and access restrictions in the public sector.');

-- GP23 | Gestão de Privacidade | Avançado
INSERT INTO public.tb_competencias(fk_dominio_conhecimento, fk_area_conhecimento, fk_dificuldade, no_origem_competencias_pt, no_origem_competencias_en, no_competencias_pt, no_competencias_en, ds_competencias_pt, ds_competencias_en)
VALUES (1, 1, 4, 'Assessment of Competences for LGPD DPO through ANPD Standard and Information Systems Curriculum', 'Assessment of Competences for LGPD DPO through ANPD Standard and Information Systems Curriculum', 'Princípios éticos aplicados à privacidade', 'Ethical principles applied to privacy', 'Conhecimento para reconhecer dilemas éticos no tratamento de dados, preservar confidencialidade, transparência, equidade, autonomia e responsabilidade, e exercer pensamento crítico, julgamento fundamentado, discrição e respeito aos direitos dos titulares, considerando impactos sociais e interesse público.', 'Knowledge to recognize ethical dilemmas in data processing; preserve confidentiality, transparency, fairness, autonomy, and responsibility; and exercise critical thinking, reasoned judgment, discretion, and respect for data subject rights, taking into account social impacts and the public interest.');

-- GP24 | Gestão de Privacidade | Especialista
