-- EP01 | Estratégias de Privacidade | Iniciante
INSERT INTO public.tb_competencias(fk_dominio_conhecimento, fk_area_conhecimento, fk_dificuldade, no_origem_competencias_pt, no_origem_competencias_en, no_competencias_pt, no_competencias_en, ds_competencias_pt, ds_competencias_en)
VALUES (1, 2, 1, 'SGD - Guia de Elaboração de Programa de Governança em Privacidade; Modelo de Política de Desenvolvimento de Pessoas em Privacidade e Segurança da Informação; Guidance on Appropriate Qualifications for a Data Protection Officer', 'SGD - Guide to Developing a Privacy Governance Program; People Development Policy Template for Privacy and Information Security; Guidance on Appropriate Qualifications for a Data Protection Officer', 'Educação e cultura de privacidade', 'Privacy education and culture', 'Conhecimento para planejar, executar e atualizar ações de conscientização e capacitação, adaptar conteúdos aos públicos e promover práticas e comportamentos organizacionais consistentes com a proteção de dados, incluindo o compromisso com aprendizagem e atualização normativa e tecnológica contínuas.', 'Knowledge to plan, implement, and update awareness and training initiatives, adapt content to target audiences, and promote organizational practices and behaviors consistent with data protection, including commitment to continuous learning and updates on regulatory and technological developments.');

