VALUES (1, 2, 3, 'Lei nº 13.709/2018 (LGPD); ISO/IEC 29100; SGD - Guia sobre Privacidade desde a Concepção e por Padrão', 'Law nº 13.709/2018 (LGPD); ISO/IEC 29100; SGD - Guide to Privacy by Design and by Default', 'Minimização de dados', 'Data minimization', 'Conhecimento para limitar coleta, uso, acesso, compartilhamento e retenção ao estritamente necessário para finalidades legítimas e documentadas.', 'Knowledge to limit collection, use, access, sharing, and retention to what is strictly necessary for legitimate and documented purposes.');

-- EP10 | Estratégias de Privacidade | Intermediário
INSERT INTO public.tb_competencias(fk_dominio_conhecimento, fk_area_conhecimento, fk_dificuldade, no_origem_competencias_pt, no_origem_competencias_en, no_competencias_pt, no_competencias_en, ds_competencias_pt, ds_competencias_en)
VALUES (1, 2, 3, 'Lei nº 13.709/2018 (LGPD); ISO/IEC 29151', 'Law nº 13.709/2018 (LGPD); ISO/IEC 29151', 'Minimização da exposição de dados pessoais sensíveis', 'Minimizing the exposure of sensitive personal data', 'Conhecimento para aplicar segregação, redução de granularidade, limitação de acesso e outras medidas organizacionais e de privacidade que reduzam exposição desnecessária de dados sensíveis.', 'Knowledge to apply segregation, reduced granularity, access restrictions, and other organizational and privacy measures that reduce unnecessary exposure of sensitive data.');

-- EP11 | Estratégias de Privacidade | Intermediário
INSERT INTO public.tb_competencias(fk_dominio_conhecimento, fk_area_conhecimento, fk_dificuldade, no_origem_competencias_pt, no_origem_competencias_en, no_competencias_pt, no_competencias_en, ds_competencias_pt, ds_competencias_en)
VALUES (1, 2, 3, 'Lei nº 13.709/2018 (LGPD); SGD - Guia de Elaboração de Programa de Governança em Privacidade; Modelo de Política de Proteção de Dados Pessoais', 'Law nº 13.709/2018 (LGPD); SGD - Guide to Developing a Privacy Governance Program; Personal Data Protection Policy Template', 'Elaboração e implementação de políticas e procedimentos de privacidade', 'Development and implementation of privacy policies and procedures', 'Conhecimento para transformar requisitos legais e organizacionais em políticas, procedimentos, responsabilidades e fluxos de trabalho aplicáveis às operações de tratamento, traduzindo exigências normativas em processos executáveis e articulando soluções proporcionais que conciliem proteção de dados, finalidade pública e funcionamento organizacional.', 'Knowledge to translate legal and organizational requirements into policies, procedures, responsibilities, and workflows applicable to processing operations, turning regulatory requirements into executable processes and coordinating proportionate solutions that reconcile data protection, public purposes, and organizational operations.');

-- EP12 | Estratégias de Privacidade | Avançado
INSERT INTO public.tb_competencias(fk_dominio_conhecimento, fk_area_conhecimento, fk_dificuldade, no_origem_competencias_pt, no_origem_competencias_en, no_competencias_pt, no_competencias_en, ds_competencias_pt, ds_competencias_en)
VALUES (1, 2, 4, 'ENISA - Data Protection Engineering; SGD - Guia sobre Privacidade desde a Concepção e por Padrão', 'ENISA - Data Protection Engineering; SGD - Guide to Privacy by Design and by Default', 'Engenharia de proteção de dados', 'Data protection engineering', 'Conhecimento sobre técnicas e tecnologias usadas para transformar princípios e requisitos de proteção de dados em medidas técnicas e organizacionais verificáveis, incluindo seleção, especificação e verificação de controles de acesso, criptografia e monitoramento, quando pertinentes, em articulação com as equipes de TI e segurança da informação.', 'Knowledge of techniques and technologies used to translate data protection principles and requirements into verifiable technical and organizational measures, including the selection, specification, and verification of access controls, encryption, and monitoring where relevant, in coordination with IT and information security teams.');

